// Reference.jsx: NASA's own sonification, with its original soundtrack, for comparison.
// This plays NASA's file as-is. It is not generated by our engine.
export default function Reference({ entry }) {
  if (!entry) return null
  return (
    <section className="reference" aria-labelledby="ref-h">
      <h2 id="ref-h">How NASA does it</h2>
      <p>{entry.note}</p>
      {entry.file ? (
        <video src={entry.file} controls preload="none" />
      ) : (
        <p className="muted">
          Not downloaded yet. Run <code>npm run fetch:nasa</code>, or{' '}
          <a href={entry.source} target="_blank" rel="noreferrer">watch it on NASA's site</a>.
        </p>
      )}
      <p className="muted">Credit: {entry.credit}</p>
    </section>
  )
}
